/** @param {import('./engine.js').State} state */
export function cowFollowups(state){const g=state.cow;return [{id:'cow.happy',title:'cowHappyGoal',detail:'cowHappyHelp',ready:!!g&&g.stats.healthyHours>=72,progress:Math.min(72,g?.stats.healthyHours||0)+'/72 h',target:'[data-choose-cow=feed]'},{id:'cow.cool',title:'cowCoolGoal',detail:'cowCoolHelp',ready:!!g&&g.cooler.owned&&g.stats.validCooledHours>=24,progress:Math.min(24,g?.stats.validCooledHours||0)+'/24 h',target:'[data-choose-cow=can]'},{id:'cow.heat',title:'cowHeatGoal',detail:'cowHeatHelp',ready:!!g&&!!g.barn?.shade&&g.stats.hotShadeHours>=24,progress:Math.min(24,g?.stats.hotShadeHours||0)+'/24 h',target:'#market-open'},{id:'cow.bigger',title:'cowBiggerGoal',detail:'cowBiggerHelp',ready:!!g&&!!g.barn?.expanded&&g.stats.purchasedCows===1&&g.cows.length===3,progress:(g?.cows.length||0)+'/3',target:'#market-open'}];}
/** Monotonic objectives use accepted engine evidence; goals are cosmetic, contract bonuses are separate. @param {import('./engine.js').State} state */
export function advanceCowMission(state){const g=state.cow;if(!g?.visited)return;const checks=[g.visited,g.stats.feedActions>0,g.stats.waterActions>0,g.stats.standCleaned>0,g.mission.inspectedA,g.stats.milkings>0,g.stats.saleCount>0,g.mission.upgradeViewed];while(g.mission.step<checks.length&&checks[g.mission.step])g.mission.step++;if(g.mission.step>=7&&!g.grants.includes('cow.welcome'))g.grants.push('cow.welcome');if(g.mission.step>=8)for(const goal of cowFollowups(state))if(goal.ready&&!g.grants.includes(goal.id))g.grants.push(goal.id);}
/** @param {import('./engine.js').State} state */
export function cowObjective(state){const step=state.cow?.mission.step||0,targets=['#area-cow','[data-choose-cow=feed]','[data-choose-cow=water]','[data-choose-cow=stand]','[data-choose-cow="cow.starter.a"]','[data-choose-cow="cow.starter.a"]','[data-choose-cow=coop]','#market-open',''];if(step>=8){const goal=cowFollowups(state).find(goal=>!state.cow?.grants.includes(goal.id));if(goal)return {...goal,step};}return {step,title:'cowMission'+step,detail:'cowDetail'+step,target:targets[step],progress:''};}
